<?php
function page_start(string $title, array $user): void {
    $role = $user['role'];
    $links = $role === 'admin'
        ? ['dashboard.php'=>['📊','Dashboard'],'employees.php'=>['👥','Employees'],'departments.php'=>['🏢','Departments'],'attendance.php'=>['🕒','Attendance'],'leave.php'=>['🌴','Leave'],'reports.php'=>['📈','Reports'],'salary.php'=>['💰','Salary Management'],'feedback.php'=>['💬','Feedback']]
        : ['dashboard.php'=>['📊','My Dashboard'],'profile.php'=>['👤','My Profile'],'attendance.php'=>['🕒','My Attendance'],'leave.php'=>['🌴','My Leave'],'payslips.php'=>['🧾','My Payslips'],'feedback.php'=>['💬','Feedback']];
    ?><!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=h($title)?> | EMS</title><link rel="stylesheet" href="<?=h(url('css/style.css'))?>?v=<?=filemtime(__DIR__.'/../css/style.css')?>"></head><body><div class="app"><aside class="sidebar"><div class="brand"><h2>EMS</h2><p><?=h(ucfirst($role))?> Portal</p></div><?php foreach ($links as $path=>[$icon,$label]): ?><a class="nav-link <?=basename($_SERVER['SCRIPT_NAME']) === $path ? 'active' : ''?>" href="<?=h(url($role.'/'.$path))?>"><span class="nav-icon" aria-hidden="true"><?=$icon?></span><span><?=h($label)?></span></a><?php endforeach; ?><form class="sidebar-logout" action="<?=h(url('logout.php'))?>" method="post"><?=csrf_field()?><button type="submit" class="nav-link logout-button">↩ Logout</button></form></aside><div class="main"><header class="topbar"><div class="topbar-left"><button id="menuToggle" class="menu-toggle" aria-label="Toggle navigation">☰</button><span class="topbar-title"><?=h($title)?></span></div><div class="topbar-right"><span class="user-info">👤 <?=h($user['full_name'])?></span></div></header><main class="content"><div class="page-header"><div><h1><?=h($title)?></h1></div></div><?php show_flash();
}
function page_end(): void { ?></main><footer>© 2026 Employee Management System</footer></div></div><script src="<?=h(url('js/main.js'))?>"></script><script src="<?=h(url('js/backend-ui.js'))?>"></script></body></html><?php }
function input_field(string $key, string $label, $value = '', string $type = 'text', bool $required = true, string $extra = ''): void { ?><div class="form-group"><label for="<?=h($key)?>"><?=h($label)?></label><input class="form-control" id="<?=h($key)?>" name="<?=h($key)?>" type="<?=h($type)?>" value="<?=h($value)?>" <?=$required?'required':''?> <?=$extra?>></div><?php }
